/* Diagramme de payoff : forward et options selon le prix du sous-jacent à l'échéance */
(function () {
  var svg = document.getElementById("pf-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }
  var NAMES = {
    fr:["Long call","Short call","Long put","Short put","Long forward","Short forward"],
    en:["Long call","Short call","Long put","Short put","Long forward","Short forward"],
    nl:["Long call","Short call","Long put","Short put","Long forward","Short forward"]
  };
  function unl(){ return al()==="en"?"unlimited":(al()==="nl"?"onbeperkt":"illimité"); }

  function payoff(inst, K, prem, S){
    switch(inst){
      case 0: return Math.max(S-K,0)-prem;         // long call
      case 1: return prem-Math.max(S-K,0);         // short call
      case 2: return Math.max(K-S,0)-prem;         // long put
      case 3: return prem-Math.max(K-S,0);         // short put
      case 4: return S-K;                          // long forward
      case 5: return K-S;                          // short forward
    }
    return 0;
  }

  function draw(){
    var inst=Math.round(v("pf-inst")), K=v("pf-k"), prem=v("pf-prem");
    var isFwd = (inst>=4);
    setT("pf-inst-o", NAMES[al()][inst]||NAMES.fr[inst]);
    setT("pf-k-o", K.toFixed(0)); setT("pf-prem-o", isFwd?"—":prem.toFixed(1));

    // domaine S de 0 à 2K
    var Smax=2*K;
    // valeurs remarquables
    var be, maxg, maxl;
    if (inst===0){ be=K+prem; maxg=unl(); maxl=(-prem).toFixed(1); }
    else if (inst===1){ be=K+prem; maxg=prem.toFixed(1); maxl="−"+unl(); }
    else if (inst===2){ be=K-prem; maxg=(K-prem).toFixed(1); maxl=(-prem).toFixed(1); }
    else if (inst===3){ be=K-prem; maxg=prem.toFixed(1); maxl=(-(K-prem)).toFixed(1); }
    else if (inst===4){ be=K; maxg=unl(); maxl=(-K).toFixed(1); }
    else { be=K; maxg=K.toFixed(1); maxl="−"+unl(); }
    setT("pf-be", be.toFixed(1)); setT("pf-max", maxg); setT("pf-min", maxl);

    // échelle y : balayer le domaine
    var ys=[], xs=[];
    for (var i=0;i<=120;i++){ var S=Smax*i/120; xs.push(S); ys.push(payoff(inst,K,prem,S)); }
    var ymin=Math.min.apply(null,ys), ymax=Math.max.apply(null,ys);
    var pad=(ymax-ymin)*0.12||1; ymin-=pad; ymax+=pad;

    var W=520,H=300,L=46,R=16,T0=16,B=34, pw=W-L-R, ph=H-T0-B;
    function px(S){ return L + S/Smax*pw; }
    function py(val){ return T0 + (1-(val-ymin)/(ymax-ymin))*ph; }

    var g="";
    // ligne zéro
    if (ymin<0 && ymax>0){ g+='<line x1="'+L+'" y1="'+py(0).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(0).toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="2 4" opacity="0.5"/>'; }
    // strike
    g+='<line x1="'+px(K).toFixed(1)+'" y1="'+T0+'" x2="'+px(K).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--gold)" stroke-width="1.2" stroke-dasharray="4 3"/>';
    g+='<text class="tick" x="'+px(K).toFixed(1)+'" y="'+(T0+ph+14)+'" text-anchor="middle" fill="var(--gold)">K='+K.toFixed(0)+'</text>';
    // courbe de payoff
    var d="";
    for (i=0;i<xs.length;i++){ d+=(i===0?"M ":" L ")+px(xs[i]).toFixed(1)+","+py(ys[i]).toFixed(1); }
    g+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2.4"/>';
    // break-even marqueur
    if (be>0 && be<Smax){ g+='<circle cx="'+px(be).toFixed(1)+'" cy="'+py(0).toFixed(1)+'" r="3.5" fill="var(--crimson)"/>'; }
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+T0+'" x2="'+L+'" y2="'+(T0+ph)+'"/>';
    // libellés
    var xlab = al()==="en"?"underlying Sₜ":(al()==="nl"?"onderliggende Sₜ":"sous-jacent Sₜ");
    var ylab = al()==="en"?"payoff":(al()==="nl"?"payoff":"payoff");
    g+='<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xlab+'</text>';
    g+='<text class="lab" x="'+L+'" y="'+(T0-4)+'" text-anchor="start">'+ylab+'</text>';
    svg.innerHTML=g;
  }
  ["pf-inst","pf-k","pf-prem"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
